<body>
    <h1>MapleSure SponsorConnect</h1>
    <div id="how-it-works">
        <h2>How it Works</h2>
        <ol>
            <li>Enter the policy number and member ID, then click 'Look up member'.</li>
            <li>Fill in the claim details and upload any relevant documents.</li>
            <li>Submit the form to complete the claim process.</li>
        </ol>
    </div>
    <form id="claim-form">
        <div class="form-group">
            <label for="policy-number">Policy Number</label>
            <input type="text" id="policy-number">
        </div>
        <div class="form-group">
            <label for="member-id">Member ID</label>
            <input type="text" id="member-id">
        </div>
        <input type="button" value="Look up member" onclick="lookUpMember()">
        <div id="member-details"></div>
        <div class="form-group">
            <label for="last-day-worked">Last Day Worked</label>
            <input type="date" id="last-day-worked">
        </div>
        <div class="form-group">
            <label for="first-day-absent">First Day Absent</label>
            <input type="date" id="first-day-absent">
        </div>
        <div class="form-group">
            <label for="nature-of-absence">Nature of Absence</label>
            <select id="nature-of-absence">
                <option value="illness">Illness</option>
                <option value="accident">Accident</option>
                <option value="other">Other</option>
            </select>
        </div>
        <div class="form-group">
            <label for="details">Details</label>
            <textarea id="details" rows="4"></textarea>
        </div>
        <div class="form-group">
            <label for="documents">Upload Documents</label>
            <input type="file" id="documents" multiple onchange="updateDocumentList()">
            <div id="document-list"></div>
        </div>
        <input type="submit" value="Submit" onclick="submitForm(); return false;">
    </form>
    <div id="confirmation" style="display: none;"></div>
    <div class="footer-note">MapleSure Insurance — fictional demo application.</div>
    <script>
        const mockData = {
            '1001': 'Member A details',
            '1002': 'Member B details'
        };

        function lookUpMember() {
            const memberId = document.getElementById('member-id').value;
            const policyNumber = document.getElementById('policy-number').value;
            if (mockData[memberId]) {
                document.getElementById('member-details').textContent = 'Policy: ' + policyNumber + ' - ' + mockData[memberId];
            } else {
                document.getElementById('member-details').textContent = 'No member found';
            }
        }

        function updateDocumentList() {
            const input = document.getElementById('documents');
            const list = document.getElementById('document-list');
            list.innerHTML = '';
            for (let i = 0; i < input.files.length; i++) {
                const file = input.files[i];
                const li = document.createElement('li');
                li.textContent = file.name;
                list.appendChild(li);
            }
        }

        function submitForm() {
            document.getElementById('claim-form').style.display = 'none';
            const confirmation = document.getElementById('confirmation');
            const referenceNumber = 'MS-2026-08-' + Math.floor(1000 + Math.random() * 9000);
            confirmation.innerHTML = '<h2>Claim Submitted</h2><p>Reference Number: ' + referenceNumber + '</p><p>Status: Received</p>';
            confirmation.style.display = 'block';
        }
    </script>
</body>
</html>

